import { createMiddleware } from 'hono/factory';
import type { AppEnv, User } from './env';

/**
 * Access codes are long random strings generated by `npm run user:add`,
 * so an unsalted SHA-256 is enough: there is nothing to brute-force.
 */
export async function hashAccessCode(code: string): Promise<string> {
  const data = new TextEncoder().encode(normalizeAccessCode(code));
  const digest = await crypto.subtle.digest('SHA-256', data);
  return [...new Uint8Array(digest)].map((byte) => byte.toString(16).padStart(2, '0')).join('');
}

export function normalizeAccessCode(code: string): string {
  return code.replace(/[\s-]/g, '').toUpperCase();
}

interface UserRow {
  id: number;
  name: string;
  daily_message_limit: number;
}

export async function findUserByCode(db: D1Database, code: string): Promise<User | null> {
  if (normalizeAccessCode(code).length < 16) return null;

  const row = await db
    .prepare('SELECT id, name, daily_message_limit FROM users WHERE code_hash = ?')
    .bind(await hashAccessCode(code))
    .first<UserRow>();

  return row ? { id: row.id, name: row.name, dailyMessageLimit: row.daily_message_limit } : null;
}

export const requireUser = createMiddleware<AppEnv>(async (c, next) => {
  const header = c.req.header('Authorization') ?? '';
  const code = header.startsWith('Bearer ') ? header.slice('Bearer '.length) : '';
  const user = code ? await findUserByCode(c.env.DB, code) : null;

  if (!user) return c.json({ error: 'invalid_code' }, 401);

  c.set('user', user);
  await next();
});
